import type { ImageSourcePropType } from 'react-native';
import { GENERATED_SPOT_ASSETS } from './spotAssets.generated';

// Two asset families per spot (visual spec v0.2 §9):
//   A. Collection Diorama — full scene for Passport, Spot Detail, Unlock, Share.
//   B. World Token        — transparent hero-only cut-out placed on Taiwan World.
// Files live in assets/spots/<id>/{collection,world}/; the registry is
// generated by scripts/generate-asset-registry.mjs.

export type CollectionVariant = 'day' | 'sunset' | 'night';

export interface SpotAssetSet {
  collection?: Partial<Record<CollectionVariant | 'thumbnail' | 'silhouette', ImageSourcePropType>>;
  world?: ImageSourcePropType;
}

// Warm background colour shared by the square collectible scenes and cards.
export const DIORAMA_BG = '#F2EDE2';

/** Collection diorama for a spot, falling back to the day render. Null = use procedural art. */
export function collectionImage(
  spotId: string,
  variant: CollectionVariant = 'day',
): ImageSourcePropType | null {
  const c = GENERATED_SPOT_ASSETS[spotId]?.collection;
  return c?.[variant] ?? c?.day ?? null;
}

/** 512px thumbnail for grids (spec §14), falling back to the full render. */
export function collectionThumbnail(spotId: string): ImageSourcePropType | null {
  return GENERATED_SPOT_ASSETS[spotId]?.collection?.thumbnail ?? collectionImage(spotId);
}

/** White cut-out of the model on transparency, tinted in the app for sealed collections (spec §3.2). */
export function silhouetteImage(spotId: string): ImageSourcePropType | null {
  return GENERATED_SPOT_ASSETS[spotId]?.collection?.silhouette ?? null;
}

/** Transparent landmark token for the world map. Null = render a generic marker. */
export function worldToken(spotId: string): ImageSourcePropType | null {
  return GENERATED_SPOT_ASSETS[spotId]?.world ?? null;
}
